-- WRITTEN, NOT EXECUTED — local disposable database only; all fixtures roll back.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select plan(170);
create function public.s31_claims(p_user uuid) returns void language sql set search_path = '' as $$
 select pg_catalog.set_config('request.jwt.claims',pg_catalog.json_build_object('sub',p_user,'role','authenticated')::text,true)
$$;
-- Returns a SQLSTATE without committing successful mutations: the inner subtransaction is always rolled back.
create function public.s31_state(p_sql text) returns text language plpgsql set search_path = '' as $$
begin
 begin
   execute p_sql;
   raise exception using errcode = 'P9901', message = 'test_rollback_success';
 exception when sqlstate 'P9901' then return '00000'; when others then return sqlstate;
 end;
end;
$$;
grant execute on function public.s31_state(text),public.s31_claims(uuid) to authenticated;
create function public.s31_hash(p_bytes bytea) returns text language sql security definer set search_path = '' as $$ select public.sha256_hex(p_bytes) $$;
grant execute on function public.s31_hash(bytea) to authenticated;
create temporary table pg_temp.s31_data (key text primary key, value jsonb);
grant all on pg_temp.s31_data to authenticated;
select public.s31_claims('33333333-3333-4333-8333-333333333333');
set local role authenticated;
insert into pg_temp.s31_data values ('template',to_jsonb(public.duplicate_document_template('classic','Studio test')));
select public.set_default_document_template((select (value ->> 'id')::uuid from pg_temp.s31_data where key = 'template'));
insert into pg_temp.s31_data values ('asset',to_jsonb(public.create_document_asset('image/svg+xml',convert_to('<svg xmlns="http://www.w3.org/2000/svg"><path d="M0 0h8v8z"/></svg>','UTF8'),public.s31_hash(convert_to('<svg xmlns="http://www.w3.org/2000/svg"><path d="M0 0h8v8z"/></svg>','UTF8')))));
select public.save_organization_brand(jsonb_build_object('primary','#216b46','accent','#b45309','font','sans','logo_asset_id',(select value ->> 'id' from pg_temp.s31_data where key = 'asset'),'footer_line','Studio test','registration_line',''));
reset role;
-- Real sealed revisions, using the same quote workflow as P5 tests.
create function public.s31_make(p_key text,p_stage text) returns void language plpgsql set search_path = '' as $$
declare c jsonb; quote_id uuid; revision_id uuid;
begin
 perform public.s31_claims('11111111-1111-4111-8111-111111111111');
 c := public.create_verified_quote_draft('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','a3000000-0000-4000-8000-000000000001','INR','en-IN','GST 18%','exclusive'::public.tax_price_basis,current_date,current_date+31,gen_random_uuid());
 quote_id := (c ->> 'id')::uuid; revision_id := (c ->> 'current_revision_id')::uuid;
 perform public.save_quote_draft(quote_id,1,gen_random_uuid(),jsonb_build_object('customer_id','a3000000-0000-4000-8000-000000000001','currency_code','INR','locale','en-IN','tax_label','GST 18%','tax_mode','exclusive','discount_bps',0,'issue_date',current_date,'valid_until',current_date+31,'notes','Studio fixture','items',jsonb_build_array(jsonb_build_object('line_id',null,'product_id','a2000000-0000-4000-8000-000000000001','position',1,'quantity_scaled',1,'quantity_scale',1)),'charges','[]'::jsonb));
 if p_stage in ('submitted','issued') then perform public.submit_quote_revision(quote_id,revision_id,(select version from public.quotes where id = quote_id),gen_random_uuid()); end if;
 if p_stage = 'issued' then perform public.issue_quote_revision(quote_id,revision_id,(select version from public.quotes where id = quote_id),gen_random_uuid()); end if;
 insert into pg_temp.s31_data values (p_key,jsonb_build_object('quote_id',quote_id,'id',revision_id));
end;
$$;
select public.s31_make('issued','issued');
select public.s31_make('draft','draft');
select public.s31_make('submitted','submitted');
-- The transaction timestamp of issue can precede the rollout wall clock in a single transaction.
-- Set only global rollout metadata as owner, never a sealed revision, to exercise the new-revision path.
update public.studio_rollout set installed_at = '-infinity';
select public.s31_claims('33333333-3333-4333-8333-333333333333');
set local role authenticated;
insert into pg_temp.s31_data values ('pin',to_jsonb(public.pin_revision_layout((select (value ->> 'id')::uuid from pg_temp.s31_data where key = 'issued'))));
-- R5 list RPC: tenant scope, capability and reference counts.
select is((select count(*)::integer from public.list_document_assets()),1,'asset gallery lists tenant assets');
select ok((select is_brand_logo from public.list_document_assets() where id=(select (value ->> 'id')::uuid from pg_temp.s31_data where key='asset')),'asset gallery marks brand logo');
select is((select pinned_revision_count from public.list_document_assets() where id=(select (value ->> 'id')::uuid from pg_temp.s31_data where key='asset')),1::bigint,'asset gallery counts pinned revisions');
select public.s31_claims('44444444-4444-4444-8444-444444444444');
select is((select count(*)::integer from public.list_document_assets()),0,'asset gallery isolates another tenant');
select public.s31_claims('33333333-3333-4333-8333-333333333333');
-- R3 marker fixtures; owner setup only, no sealed revision is edited.
reset role;
select public.s31_make('no_default','issued');
select public.s31_make('old_revision','issued');
select public.s31_make('invalid_default','issued');
select public.s31_claims('33333333-3333-4333-8333-333333333333');
